      assert DecAtomsElems(m, 0) == Ok([], m);
    }
  }

  lemma AtomsRT(xs: seq<Atom>, m: seq<Tok>)
    ensures DecAtoms(EncAtoms(xs) + m) == Ok(xs, m)
    decreases xs, m
  {
    AtomsElemsRT(xs, m);
    assert EncAtoms(xs) + m == [TI(|xs|)] + (EncAtomsElems(xs) + m);
  }

  function EncV(v: V): seq<Tok>
    decreases v
  {
    match v
    case VQ(q) =>
      [TKw(330)] + EncQ(q)
    case VS(s) =>
      [TKw(331)] + EncStr(s)
    case VSet(items) =>
      [TKw(332)] + EncAtoms(items)
  }

  function DecV(ts: seq<Tok>): PR<V>
    decreases ts
  {
    if |ts| == 0 || !ts[0].TKw? then
      Fail
    else if ts[0].k == 330 then
      match DecQ(ts[1..])
      case Ok(q, r) =>
        Ok(VQ(q), r)
      case Fail() =>
        Fail
    else if ts[0].k == 331 then
      match DecStr(ts[1..])
      case Ok(s, r) =>
        Ok(VS(s), r)
      case Fail() =>
        Fail
    else if ts[0].k == 332 then
      match DecAtoms(ts[1..])
      case Ok(xs, r) =>
        Ok(VSet(xs), r)
      case Fail() =>
        Fail
    else
      Fail
  }

  lemma VRT(v: V, m: seq<Tok>)
    ensures DecV(EncV(v) + m) == Ok(v, m)
    decreases v, m
  {
    match v
    case {:split false} VQ(q) =>
      assert EncV(v) + m == [TKw(330)] + (EncQ(q) + m);
      QRT(q, m);
    case {:split false} VS(s) =>
      assert EncV(v) + m == [TKw(331)] + (EncStr(s) + m);
      StrRT(s, m);
    case {:split false} VSet(items) =>
      assert EncV(v) + m == [TKw(332)] + (EncAtoms(items) + m);
      AtomsRT(items, m);
  }

  function EncTerm(t: Term): seq<Tok>
    decreases t
  {
    match t
    case Param(p, ty) =>
      [TKw(340)] + (EncStr(p) + EncTy(ty))
    case Lit(v) =>
      [TKw(341)] + EncV(v)
    case HistAgg(b, u) =>
      [TKw(342)] + (EncStr(b) + EncUnit(u))
  }

  function DecTerm(ts: seq<Tok>): PR<Term>
    decreases ts
  {
    if |ts| == 0 || !ts[0].TKw? then
      Fail
    else if ts[0].k == 340 then
      match DecStr(ts[1..])
      case Fail() =>
        Fail
      case Ok(p, r1) =>
        match DecTy(r1)
        case Fail() =>
          Fail
        case Ok(ty, r2) =>
          Ok(Param(p, ty), r2)
    else if ts[0].k == 341 then
      match DecV(ts[1..])
      case Ok(v, r) =>
        Ok(Lit(v), r)
      case Fail() =>
        Fail
    else if ts[0].k == 342 then
      match DecStr(ts[1..])
      case Fail() =>
        Fail
      case Ok(b, r1) =>
        match DecUnit(r1)
        case Fail() =>
          Fail
        case Ok(u, r2) =>
          Ok(HistAgg(b, u), r2)
    else
      Fail
  }

  lemma TermRT(t: Term, m: seq<Tok>)
    ensures DecTerm(EncTerm(t) + m) == Ok(t, m)
    decreases t, m
  {
    match t
    case {:split false} Param(p, ty) =>
      assert EncTerm(t) + m == [TKw(340)] + (EncStr(p) + (EncTy(ty) + m));
      StrRT(p, EncTy(ty) + m);
      TyRT(ty, m);
    case {:split false} Lit(v) =>
      assert EncTerm(t) + m == [TKw(341)] + (EncV(v) + m);
      VRT(v, m);
    case {:split false} HistAgg(b, u) =>
      assert EncTerm(t) + m == [TKw(342)] + (EncStr(b) + (EncUnit(u) + m));
      StrRT(b, EncUnit(u) + m);
      UnitRT(u, m);
  }

  function OpIdx(op: Op): int
    decreases op
  {
    match op
    case Eq() =>
      0
    case Ne() =>
      1
    case Lt() =>
      2
    case Lte() =>
      3
    case Gt() =>
      4
    case Gte() =>
      5
    case In() =>
      6
    case Nin() =>
      7
  }

  function EncOp(op: Op): seq<Tok>
    decreases op
  {
    [TKw(350 + OpIdx(op))]
  }

  function DecOp(ts: seq<Tok>): PR<Op>
    decreases ts
  {
    if |ts| == 0 || !ts[0].TKw? then
      Fail
    else if ts[0].k == 350 then
      Ok(Eq, ts[1..])
    else if ts[0].k == 351 then
      Ok(Ne, ts[1..])
    else if ts[0].k == 352 then
      Ok(Lt, ts[1..])
    else if ts[0].k == 353 then
      Ok(Lte, ts[1..])
    else if ts[0].k == 354 then
      Ok(Gt, ts[1..])
    else if ts[0].k == 355 then
      Ok(Gte, ts[1..])
    else if ts[0].k == 356 then
      Ok(In, ts[1..])
    else if ts[0].k == 357 then
      Ok(Nin, ts[1..])
    else
      Fail
  }

  lemma OpRT(op: Op, m: seq<Tok>)
    ensures DecOp(EncOp(op) + m) == Ok(op, m)
    decreases op, m
  {
    match op
    case {:split false} Eq() =>
    case {:split false} Ne() =>
    case {:split false} Lt() =>
    case {:split false} Lte() =>
    case {:split false} Gt() =>
    case {:split false} Gte() =>
    case {:split false} In() =>
    case {:split false} Nin() =>
  }

  function EncCond(c: Cond): seq<Tok>
    decreases c
  {
    match c
    case CTrue() =>
      [TKw(360)]
    case Cmp(op, l, r) =>
      [TKw(361)] + (EncOp(op) + (EncTerm(l) + EncTerm(r)))
    case And(x, y) =>
      [TKw(362)] + (EncCond(x) + EncCond(y))
    case Or(x, y) =>
      [TKw(363)] + (EncCond(x) + EncCond(y))
    case Not(x) =>
      [TKw(364)] + EncCond(x)
  }

  function DecCond(ts: seq<Tok>, fuel: nat): PR<Cond>
    decreases fuel
  {
    if fuel == 0 || |ts| == 0 || !ts[0].TKw? then
      Fail
    else if ts[0].k == 360 then
      Ok(CTrue, ts[1..])
    else if ts[0].k == 361 then
      match DecOp(ts[1..])
      case Fail() =>
        Fail
      case Ok(op, r1) =>
        match DecTerm(r1)
        case Fail() =>
          Fail
        case Ok(l, r2) =>
          match DecTerm(r2)
          case Fail() =>
            Fail
          case Ok(r, r3) =>
            Ok(Cmp(op, l, r), r3)
    else if ts[0].k == 362 then
      match DecCond(ts[1..], fuel - 1)
      case Fail() =>
        Fail
      case Ok(x, r1) =>
        match DecCond(r1, fuel - 1)
        case Fail() =>
          Fail
        case Ok(y, r2) =>
          Ok(And(x, y), r2)
    else if ts[0].k == 363 then
      match DecCond(ts[1..], fuel - 1)
      case Fail() =>
        Fail
      case Ok(x, r1) =>
        match DecCond(r1, fuel - 1)
        case Fail() =>
          Fail
        case Ok(y, r2) =>
          Ok(Or(x, y), r2)
    else if ts[0].k == 364 then
      match DecCond(ts[1..], fuel - 1)
      case Ok(x, r) =>
        Ok(Not(x), r)
      case Fail() =>
        Fail
    else
      Fail
  }

  function DecCondTop(ts: seq<Tok>): PR<Cond>
    decreases ts
  {
    DecCond(ts, |ts|)
  }

  function Depth(c: Cond): nat
    decreases c
  {
    match c
    case CTrue() =>
      1
    case Cmp(_ /* _v0 */, _ /* _v1 */, _ /* _v2 */) =>
      1
    case And(x, y) =>
      1 + if Depth(x) >= Depth(y) then Depth(x) else Depth(y)
    case Or(x, y) =>
      1 + if Depth(x) >= Depth(y) then Depth(x) else Depth(y)
    case Not(x) =>
      1 + Depth(x)
  }

  lemma /*{:_inductionTrigger Depth(c)}*/ /*{:_inductionTrigger EncCond(c)}*/ /*{:_induction c}*/ LenGeDepth(c: Cond)
    ensures |EncCond(c)| >= Depth(c)
    decreases c
  {
    match c
    case {:split false} CTrue() =>
    case {:split false} Cmp(_ /* _v3 */, _ /* _v4 */, _ /* _v5 */) =>
    case {:split false} And(x, y) =>
      LenGeDepth(x);
      LenGeDepth(y);
    case {:split false} Or(x, y) =>
      LenGeDepth(x);
      LenGeDepth(y);
    case {:split false} Not(x) =>
      LenGeDepth(x);
  }

  lemma /*{:_inductionTrigger DecCond(EncCond(c) + m, fuel)}*/ /*{:_induction c, m, fuel}*/ CondRT(c: Cond, m: seq<Tok>, fuel: nat)
    requires fuel >= Depth(c)
    ensures DecCond(EncCond(c) + m, fuel) == Ok(c, m)
    decreases c
  {
    match c
    case {:split false} CTrue() =>
    case {:split false} Cmp(op, l, r) =>
      assert EncCond(c) + m == [TKw(361)] + (EncOp(op) + (EncTerm(l) + (EncTerm(r) + m)));
      OpRT(op, EncTerm(l) + (EncTerm(r) + m));
      TermRT(l, EncTerm(r) + m);
      TermRT(r, m);
    case {:split false} And(x, y) =>
      assert EncCond(c) + m == [TKw(362)] + (EncCond(x) + (EncCond(y) + m));
      CondRT(x, EncCond(y) + m, fuel - 1);
      CondRT(y, m, fuel - 1);
    case {:split false} Or(x, y) =>
      assert EncCond(c) + m == [TKw(363)] + (EncCond(x) + (EncCond(y) + m));
      CondRT(x, EncCond(y) + m, fuel - 1);
      CondRT(y, m, fuel - 1);
    case {:split false} Not(x) =>
      assert EncCond(c) + m == [TKw(364)] + (EncCond(x) + m);
      CondRT(x, m, fuel - 1);
  }

  lemma /*{:_inductionTrigger PR<Cond>.Ok(c, m)}*/ /*{:_inductionTrigger EncCond(c)}*/ /*{:_induction c}*/ CondTopRT(c: Cond, m: seq<Tok>)
    ensures DecCondTop(EncCond(c) + m) == Ok(c, m)
    decreases c, m
  {
    LenGeDepth(c);
    CondRT(c, m, |EncCond(c) + m|);
  }

  function EncPart(p: ResPart): seq<Tok>
    decreases p
  {
    match p
    case PartExact(id) =>
      [TKw(375)] + EncStr(id)
    case PartOneOf(ids) =>
      [TKw(376)] + EncStrs(ids)
    case PartRelated(rel, anchor) =>
      [TKw(377)] + (EncStr(rel) + EncStr(anchor))
  }

  function DecPart(ts: seq<Tok>): PR<ResPart>
    decreases ts
  {
    if |ts| == 0 || !ts[0].TKw? then
      Fail
    else if ts[0].k == 375 then
      match DecStr(ts[1..])
      case Ok(id, r) =>
        Ok(PartExact(id), r)
      case Fail() =>
        Fail
    else if ts[0].k == 376 then
      match DecStrs(ts[1..])
      case Ok(ids, r) =>
        Ok(PartOneOf(ids), r)
      case Fail() =>
        Fail
    else if ts[0].k == 377 then
      match DecStr(ts[1..])
      case Fail() =>
        Fail
      case Ok(rel, r1) =>
        match DecStr(r1)
        case Fail() =>
          Fail
        case Ok(anchor, r2) =>
          Ok(PartRelated(rel, anchor), r2)
    else
      Fail
  }

  lemma PartRT(p: ResPart, m: seq<Tok>)
    ensures DecPart(EncPart(p) + m) == Ok(p, m)
    decreases p, m
  {
    match p
    case {:split false} PartExact(id) =>
      assert EncPart(p) + m == [TKw(375)] + (EncStr(id) + m);
      StrRT(id, m);
    case {:split false} PartOneOf(ids) =>
      assert EncPart(p) + m == [TKw(376)] + (EncStrs(ids) + m);
      StrsRT(ids, m);
    case {:split false} PartRelated(rel, anchor) =>
      assert EncPart(p) + m == [TKw(377)] + (EncStr(rel) + (EncStr(anchor) + m));
      StrRT(rel, EncStr(anchor) + m);
      StrRT(anchor, m);
  }

  function EncPartsElems(xs: seq<ResPart>): seq<Tok>
    decreases xs
  {
    if |xs| == 0 then
      []
    else
      EncPart(xs[0]) + EncPartsElems(xs[1..])
  }

  function EncParts(xs: seq<ResPart>): seq<Tok>
    decreases xs
  {
    [TI(|xs|)] + EncPartsElems(xs)
  }

  function DecPartsElems(ts: seq<Tok>, n: nat): PR<seq<ResPart>>
    decreases n
  {
    if n == 0 then
      Ok([], ts)
    else
      match DecPart(ts) case Fail() => Fail case Ok(x, r) => match DecPartsElems(r, n - 1) case Fail() => Fail case Ok(xs, r2) => Ok([x] + xs, r2)
  }

  function DecParts(ts: seq<Tok>): PR<seq<ResPart>>
    decreases ts
  {
    if |ts| > 0 && ts[0].TI? && ts[0].i >= 0 then
      DecPartsElems(ts[1..], ts[0].i)
    else
      Fail
  }

  lemma /*{:_inductionTrigger PR<seq<ResPart>>.Ok(xs, m)}*/ /*{:_inductionTrigger EncPartsElems(xs) + m}*/ /*{:_induction xs, m}*/ PartsElemsRT(xs: seq<ResPart>, m: seq<Tok>)
    ensures DecPartsElems(EncPartsElems(xs) + m, |xs|) == Ok(xs, m)
    decreases xs
  {
    if |xs| > 0 {
      ghost var rest := EncPartsElems(xs[1..]);
      assert EncPartsElems(xs) + m == EncPart(xs[0]) + (rest + m);
      PartRT(xs[0], rest + m);
      PartsElemsRT(xs[1..], m);
      assert |xs[1..]| == |xs| - 1;
      assert xs == [xs[0]] + xs[1..];
      assert DecPart(EncPart(xs[0]) + (rest + m)) == Ok(xs[0], rest + m);
      assert DecPartsElems(rest + m, |xs| - 1) == Ok(xs[1..], m);
    } else {
      assert xs == [];
      assert EncPartsElems(xs) == [];
      assert EncPartsElems(xs) + m == m;
      assert |xs| == 0;
      assert DecPartsElems(m, 0) == Ok([], m);
    }
  }

  lemma PartsRT(xs: seq<ResPart>, m: seq<Tok>)
    ensures DecParts(EncParts(xs) + m) == Ok(xs, m)
    decreases xs, m
  {
    PartsElemsRT(xs, m);
    assert EncParts(xs) + m == [TI(|xs|)] + (EncPartsElems(xs) + m);
  }

  function EncResSel(s: ResSel): seq<Tok>
    decreases s
  {
    match s
    case Exact(id) =>
      [TKw(370)] + EncStr(id)
    case OneOf(ids) =>
      [TKw(371)] + EncStrs(ids)
    case Related(rel, anchor) =>
      [TKw(372)] + (EncStr(rel) + EncStr(anchor))
    case AnyRes(reason) =>
      [TKw(373)] + EncStr(reason)
    case AllOf(ps) =>
      [TKw(374)] + EncParts(ps)
  }

  function DecResSel(ts: seq<Tok>): PR<ResSel>
    decreases ts
  {
    if |ts| == 0 || !ts[0].TKw? then
      Fail
    else if ts[0].k == 370 then
      match DecStr(ts[1..])
      case Ok(id, r) =>
        Ok(Exact(id), r)
      case Fail() =>
        Fail
    else if ts[0].k == 371 then
      match DecStrs(ts[1..])
      case Ok(ids, r) =>
        Ok(OneOf(ids), r)
      case Fail() =>
        Fail
    else if ts[0].k == 372 then
      match DecStr(ts[1..])
      case Fail() =>
        Fail
      case Ok(rel, r1) =>
        match DecStr(r1)
        case Fail() =>
          Fail
        case Ok(anchor, r2) =>
          Ok(Related(rel, anchor), r2)
    else if ts[0].k == 373 then
      match DecStr(ts[1..])
      case Ok(reason, r) =>
        Ok(AnyRes(reason), r)
      case Fail() =>
        Fail
    else if ts[0].k == 374 then
      match DecParts(ts[1..])
      case Ok(ps, r) =>
        Ok(AllOf(ps), r)
      case Fail() =>
        Fail
    else
      Fail
  }

  lemma ResSelRT(s: ResSel, m: seq<Tok>)
    ensures DecResSel(EncResSel(s) + m) == Ok(s, m)
    decreases s, m
  {
    match s
    case {:split false} Exact(id) =>
      assert EncResSel(s) + m == [TKw(370)] + (EncStr(id) + m);
      StrRT(id, m);
    case {:split false} OneOf(ids) =>
      assert EncResSel(s) + m == [TKw(371)] + (EncStrs(ids) + m);
      StrsRT(ids, m);
    case {:split false} Related(rel, anchor) =>
      assert EncResSel(s) + m == [TKw(372)] + (EncStr(rel) + (EncStr(anchor) + m));
      StrRT(rel, EncStr(anchor) + m);
      StrRT(anchor, m);
    case {:split false} AnyRes(reason) =>
      assert EncResSel(s) + m == [TKw(373)] + (EncStr(reason) + m);
      StrRT(reason, m);
    case {:split false} AllOf(ps) =>
      assert EncResSel(s) + m == [TKw(374)] + (EncParts(ps) + m);
      PartsRT(ps, m);
  }

