  function DecWindow(ts: seq<Tok>): PR<Window>
    decreases ts
  {
    if |ts| == 0 || !ts[0].TKw? then
      Fail
    else if ts[0].k == 420 then
      Ok(WTask, ts[1..])
    else if ts[0].k == 421 then
      match DecInt(ts[1..])
      case Ok(ms, r) =>
        Ok(WSliding(ms), r)
      case Fail() =>
        Fail
    else if ts[0].k == 422 then
      match DecInt(ts[1..])
      case Fail() =>
        Fail
      case Ok(ms, r1) =>
        match DecInt(r1)
        case Fail() =>
          Fail
        case Ok(t0, r2) =>
          Ok(WPeriod(ms, t0), r2)
    else if ts[0].k == 423 then
      Ok(WLifetime, ts[1..])
    else
      Fail
  }

