    }
  }

  lemma CondsRT(xs: seq<Cond>, m: seq<Tok>)
    ensures DecConds(EncConds(xs) + m) == Ok(xs, m)
    decreases xs, m
  {
    CondsElemsRT(xs, m);
    assert EncConds(xs) + m == [TI(|xs|)] + (EncCondsElems(xs) + m);
  }

  function EncHolesElems(xs: seq<Hole>): seq<Tok>
    decreases xs
  {
    if |xs| == 0 then
      []
    else
      EncHole(xs[0]) + EncHolesElems(xs[1..])
  }

  function EncHoles(xs: seq<Hole>): seq<Tok>
    decreases xs
  {
    [TI(|xs|)] + EncHolesElems(xs)
  }

  function DecHolesElems(ts: seq<Tok>, n: nat): PR<seq<Hole>>
    decreases n
  {
    if n == 0 then
      Ok([], ts)
    else
      match DecHole(ts) case Fail() => Fail case Ok(x, r) => match DecHolesElems(r, n - 1) case Fail() => Fail case Ok(xs, r2) => Ok([x] + xs, r2)
  }

  function DecHoles(ts: seq<Tok>): PR<seq<Hole>>
    decreases ts
  {
    if |ts| > 0 && ts[0].TI? && ts[0].i >= 0 then
      DecHolesElems(ts[1..], ts[0].i)
    else
      Fail
  }

  lemma /*{:_inductionTrigger PR<seq<Hole>>.Ok(xs, m)}*/ /*{:_inductionTrigger EncHolesElems(xs) + m}*/ /*{:_induction xs, m}*/ HolesElemsRT(xs: seq<Hole>, m: seq<Tok>)
    ensures DecHolesElems(EncHolesElems(xs) + m, |xs|) == Ok(xs, m)
    decreases xs
  {
    if |xs| > 0 {
      ghost var rest := EncHolesElems(xs[1..]);
      assert EncHolesElems(xs) + m == EncHole(xs[0]) + (rest + m);
      HoleRT(xs[0], rest + m);
      HolesElemsRT(xs[1..], m);
      assert |xs[1..]| == |xs| - 1;
      assert xs == [xs[0]] + xs[1..];
      assert DecHole(EncHole(xs[0]) + (rest + m)) == Ok(xs[0], rest + m);
      assert DecHolesElems(rest + m, |xs| - 1) == Ok(xs[1..], m);
    } else {
      assert xs == [];
      assert EncHolesElems(xs) == [];
      assert EncHolesElems(xs) + m == m;
      assert |xs| == 0;
      assert DecHolesElems(m, 0) == Ok([], m);
    }
  }

  lemma HolesRT(xs: seq<Hole>, m: seq<Tok>)
    ensures DecHoles(EncHoles(xs) + m) == Ok(xs, m)
    decreases xs, m
  {
    HolesElemsRT(xs, m);
    assert EncHoles(xs) + m == [TI(|xs|)] + (EncHolesElems(xs) + m);
  }

  function EncGoal(g: Goal): seq<Tok>
    decreases g
  {
    [TKw(480), TI(g.v), TS(g.principal), TS(g.ontDigest), TS(g.nlDigest)] + (EncStrs(g.sources) + (EncGrants(g.grants) + (EncProhibits(g.prohibits) + (EncBounds(g.bounds) + (EncValidity(g.validity) + (EncDeleg(g.deleg) + (EncConds(g.escalateOn) + (EncStrs(g.wildcardAck) + EncHoles(g.holes)))))))))
  }

  function DecGoal(ts: seq<Tok>): PR<Goal>
    decreases ts
  {
    if |ts| < 5 || ts[0] != TKw(480) || !ts[1].TI? || !ts[2].TS? || !ts[3].TS? || !ts[4].TS? then
      Fail
    else
      match DecStrs(ts[5..]) case Fail() => Fail case Ok(sources, r1) => match DecGrants(r1) case Fail() => Fail case Ok(grants, r2) => match DecProhibits(r2) case Fail() => Fail case Ok(prohibits, r3) => match DecBounds(r3) case Fail() => Fail case Ok(bounds, r4) => match DecValidity(r4) case Fail() => Fail case Ok(validity, r5) => match DecDeleg(r5) case Fail() => Fail case Ok(deleg, r6) => match DecConds(r6) case Fail() => Fail case Ok(esc, r7) => match DecStrs(r7) case Fail() => Fail case Ok(ack, r8) => match DecHoles(r8) case Fail() => Fail case Ok(holes, r9) => Ok(Goal(ts[1].i, ts[2].s, ts[3].s, ts[4].s, sources, grants, prohibits, bounds, validity, deleg, esc, ack, holes), r9)
  }

  lemma GoalRT(g: Goal, m: seq<Tok>)
    ensures DecGoal(EncGoal(g) + m) == Ok(g, m)
    decreases g, m
  {
    ghost var t9 := EncHoles(g.holes) + m;
    ghost var t8 := EncStrs(g.wildcardAck) + t9;
    ghost var t7 := EncConds(g.escalateOn) + t8;
    ghost var t6 := EncDeleg(g.deleg) + t7;
    ghost var t5 := EncValidity(g.validity) + t6;
    ghost var t4 := EncBounds(g.bounds) + t5;
    ghost var t3 := EncProhibits(g.prohibits) + t4;
    ghost var t2 := EncGrants(g.grants) + t3;
    ghost var t1 := EncStrs(g.sources) + t2;
    assert EncGoal(g) + m == [TKw(480), TI(g.v), TS(g.principal), TS(g.ontDigest), TS(g.nlDigest)] + t1;
    assert ([TKw(480), TI(g.v), TS(g.principal), TS(g.ontDigest), TS(g.nlDigest)] + t1)[5..] == t1;
    StrsRT(g.sources, t2);
    GrantsRT(g.grants, t3);
    ProhibitsRT(g.prohibits, t4);
    BoundsRT(g.bounds, t5);
    ValidityRT(g.validity, t6);
    DelegRT(g.deleg, t7);
    CondsRT(g.escalateOn, t8);
    StrsRT(g.wildcardAck, t9);
    HolesRT(g.holes, m);
  }

  function Render(g: Goal): seq<Tok>
    decreases g
  {
    EncGoal(g)
  }

  function Parse(ts: seq<Tok>): Option<Goal>
    decreases ts
  {
    match DecGoal(ts)
    case Ok(g, rest) =>
      if |rest| == 0 then
        Some(g)
      else
        None
    case Fail() =>
      None
  }

  lemma RenderParse(g: Goal)
    ensures Parse(Render(g)) == Some(g)
    decreases g
  {
    assert EncGoal(g) + [] == EncGoal(g);
    GoalRT(g, []);
  }

  lemma RenderInjective(g1: Goal, g2: Goal)
    requires Render(g1) == Render(g2)
    ensures g1 == g2
    decreases g1, g2
  {
    RenderParse(g1);
    RenderParse(g2);
  }

  import opened GoalIr

  datatype Tok = TKw(k: int) | TI(i: int) | TS(s: string)

  datatype PR<T> = Fail | Ok(v: T, rest: seq<Tok>)
}

module GoalIr {
  const Deny: Dec := 0
  const Escalate: Dec := 1
  const Allow: Dec := 2

  function MeetD(a: Dec, b: Dec): Dec
    decreases a, b
  {
    if a <= b then
      a
    else
      b
  }

  function JoinD(a: Dec, b: Dec): Dec
    decreases a, b
  {
    if a >= b then
      a
    else
      b
  }

  const KF: Tri := 0
  const KU: Tri := 1
  const KT: Tri := 2

  function AndK(a: Tri, b: Tri): Tri
    decreases a, b
  {
    if a <= b then
      a
    else
      b
  }

  function OrK(a: Tri, b: Tri): Tri
    decreases a, b
  {
    if a >= b then
      a
    else
      b
  }

  function NotK(a: Tri): Tri
    decreases a
  {
    2 - a
  }

  function B2T(b: bool): Tri
    decreases b
  {
    if b then
      KT
    else
      KF
  }

  function DecOfTri(t: Tri): Dec
    decreases t
  {
    t
  }

  function AtomV(a: Atom): V
    decreases a
  {
    match a
    case AQ(q) =>
      VQ(q)
    case AS(s) =>
      VS(s)
  }

  function TypeOfV(v: V): Option<Ty>
    decreases v
  {
    match v
    case VQ(q) =>
      Some(TyQ(q.u))
    case VS(_ /* _v0 */) =>
      Some(TyS)
    case VSet(_ /* _v1 */) =>
      None
  }

  function ResOk(p: ResPat, r: string): bool
    decreases p, r
  {
    match p
    case PStar() =>
      true
    case PSet(ids) =>
      r in ids
  }

  function RelMembers(rels: seq<RelDecl>, rel: string, anchor: string): seq<string>
    decreases rels
  {
    if |rels| == 0 then
      []
    else if rels[0].rel == rel && rels[0].anchor == anchor then
      rels[0].members
    else
      RelMembers(rels[1..], rel, anchor)
  }

  function ResolveSel(ont: Ontology, s: ResSel): ResPat
    decreases ont, s
  {
    match s
    case Exact(id) =>
      PSet([id])
    case OneOf(ids) =>
      PSet(ids)
    case Related(rel, anchor) =>
      PSet(RelMembers(ont.rels, rel, anchor))
    case AnyRes(_ /* _v2 */) =>
      PStar
    case AllOf(ps) =>
      ResolveParts(ont, ps)
  }

  function ResolvePart(ont: Ontology, p: ResPart): ResPat
    decreases ont, p
  {
    match p
    case PartExact(id) =>
      PSet([id])
    case PartOneOf(ids) =>
      PSet(ids)
    case PartRelated(rel, anchor) =>
      PSet(RelMembers(ont.rels, rel, anchor))
  }

  function FilterIn(a: seq<string>, b: seq<string>): seq<string>
    decreases a
  {
    if |a| == 0 then
      []
    else
      (if a[0] in b then [a[0]] else []) + FilterIn(a[1..], b)
  }

  function InterPat(x: ResPat, y: ResPat): ResPat
    decreases x, y
  {
    match x
    case PStar() =>
      y
    case PSet(a) =>
      match y
      case PStar() =>
        x
      case PSet(b) =>
        PSet(FilterIn(a, b))
  }

  function ResolveParts(ont: Ontology, ps: seq<ResPart>): ResPat
    decreases ps
  {
    if |ps| == 0 then
      PStar
    else
      InterPat(ResolvePart(ont, ps[0]), ResolveParts(ont, ps[1..]))
  }

  lemma /*{:_inductionTrigger FilterIn(a, b)}*/ /*{:_induction a, b}*/ FilterInMem(a: seq<string>, b: seq<string>, r: string)
    ensures r in FilterIn(a, b) <==> r in a && r in b
    decreases a
  {
    if |a| > 0 {
      assert a == [a[0]] + a[1..];
      FilterInMem(a[1..], b, r);
    }
  }

  lemma InterOk(x: ResPat, y: ResPat, r: string)
    ensures ResOk(InterPat(x, y), r) <==> ResOk(x, r) && ResOk(y, r)
    decreases x, y, r
  {
    if x.PSet? && y.PSet? {
      FilterInMem(x.ids, y.ids, r);
    }
  }

  lemma /*{:_inductionTrigger ResolveParts(ont, ps)}*/ /*{:_induction ont, ps}*/ PartsSound(ont: Ontology, ps: seq<ResPart>, r: string)
    ensures ResOk(ResolveParts(ont, ps), r) <==> forall i: int {:trigger ps[i]} :: 0 <= i < |ps| ==> ResOk(ResolvePart(ont, ps[i]), r)
    decreases ps
  {
    if |ps| > 0 {
      PartsSound(ont, ps[1..], r);
      InterOk(ResolvePart(ont, ps[0]), ResolveParts(ont, ps[1..]), r);
      assert forall i: int {:trigger ps[i]} :: 1 <= i < |ps| ==> ps[i] == ps[1..][i - 1];
    }
  }

  lemma AllOfSound(ont: Ontology, ps: seq<ResPart>, r: string)
    ensures ResOk(ResolveSel(ont, AllOf(ps)), r) <==> forall i: int {:trigger ps[i]} :: 0 <= i < |ps| ==> ResOk(ResolvePart(ont, ps[i]), r)
    decreases ont, ps, r
  {
    PartsSound(ont, ps, r);
  }

  function VerbsOfClass(vs: seq<VerbDecl>, cls: string): seq<string>
    decreases vs
  {
    if |vs| == 0 then
      []
    else
      (if vs[0].cls == cls then [vs[0].verb] else []) + VerbsOfClass(vs[1..], cls)
  }

  function ResolveBSel(ont: Ontology, s: Sel): LSel
    decreases ont, s
  {
    match s
    case SelGids(g) =>
      LSel(g, [])
    case SelEffect(c) =>
      LSel([], VerbsOfClass(ont.verbs, c))
  }

  function ProhVerbs(ont: Ontology, t: ProhTarget): seq<string>
    decreases ont, t
  {
    match t
    case PVerb(v) =>
      [v]
    case PEffect(c) =>
      VerbsOfClass(ont.verbs, c)
  }

  function EqT(x: V, y: V): Tri
    decreases x, y
  {
    match x
    case VQ(p) =>
      (match y
      case VQ(q) =>
        if p.u == q.u then
          B2T(p.n == q.n)
        else
          KU
      case _ /* _v3 */ =>
        KU)
    case VS(s) =>
      (match y
      case VS(t) =>
        B2T(s == t)
      case _ /* _v4 */ =>
        KU)
    case VSet(_ /* _v5 */) =>
      KU
  }

  function LtT(x: V, y: V): Tri
    decreases x, y
  {
    match x
    case VQ(p) =>
      (match y
      case VQ(q) =>
        if p.u == q.u then
          B2T(p.n < q.n)
        else
          KU
      case _ /* _v6 */ =>
        KU)
    case _ /* _v7 */ =>
      KU
  }

  function InT(x: V, items: seq<Atom>): Tri
    decreases items
  {
    if |items| == 0 then
      KF
    else
      OrK(EqT(x, AtomV(items[0])), InT(x, items[1..]))
  }

  function CmpT(op: Op, x: Option<V>, y: Option<V>): Tri
    decreases op, x, y
  {
    if x.None? || y.None? then
      KU
    else
      match op case Eq() => EqT(x.v, y.v) case Ne() => NotK(EqT(x.v, y.v)) case Lt() => LtT(x.v, y.v) case Gte() => NotK(LtT(x.v, y.v)) case Gt() => LtT(y.v, x.v) case Lte() => NotK(LtT(y.v, x.v)) case In() => (match y.v case VSet(items) => InT(x.v, items) case _ /* _v8 */ => KU) case Nin() => NotK(match y.v case VSet(items) => InT(x.v, items) case _ /* _v9 */ => KU)
  }

  function NegOp(op: Op): Op
    decreases op
  {
    match op
    case Eq() =>
      Ne
    case Ne() =>
      Eq
    case Lt() =>
      Gte
    case Gte() =>
      Lt
    case Gt() =>
      Lte
    case Lte() =>
      Gt
    case In() =>
      Nin
    case Nin() =>
      In
  }

  lemma NegOpSound(op: Op, x: Option<V>, y: Option<V>)
    ensures CmpT(NegOp(op), x, y) == NotK(CmpT(op, x, y))
    decreases op, x, y
  {
  }

  function EvalT(t: Term, a: Act, h: Hist): Option<V>
    decreases t, a, h
  {
    match t
    case Param(p, _ /* _v10 */) =>
      if p in a.params then
        Some(a.params[p])
      else
        None
    case Lit(v) =>
      Some(v)
    case HistAgg(b, _ /* _v11 */) =>
      if b in h.aggs then
        Some(VQ(h.aggs[b]))
      else
        None
  }

  function EvalC(c: Cond, a: Act, h: Hist): Tri
    decreases c
  {
    match c
    case CTrue() =>
      KT
    case Cmp(op, l, r) =>
      CmpT(op, EvalT(l, a, h), EvalT(r, a, h))
    case And(x, y) =>
      AndK(EvalC(x, a, h), EvalC(y, a, h))
    case Or(x, y) =>
      OrK(EvalC(x, a, h), EvalC(y, a, h))
    case Not(x) =>
      NotK(EvalC(x, a, h))
  }

  function StrIn(x: string, s: seq<string>): bool
    decreases x, s
  {
    x in s
  }

  function AppliesL(s: LSel, gid: string, verb: string): bool
    decreases s, gid, verb
  {
    gid in s.gids || verb in s.verbs
  }

  function InScope(sc: Scope, a: Act, x: Act): bool
    decreases sc, a, x
  {
    match sc
    case SSession() =>
      a.sess == x.sess
    case SPrincipal() =>
      a.prin == x.prin
    case SOrg() =>
      a.org == x.org
    case SFleet(ag) =>
      a.agent in ag &&
      x.agent in ag
  }

  function InWindow(w: Window, a: Act, x: Act): bool
    decreases w, a, x
  {
    match w
    case WTask() =>
      true
    case WLifetime() =>
      true
    case WSliding(ms) =>
      x.t > a.t - ms &&
      x.t <= a.t
    case WPeriod(ms, t0) =>
      ms > 0 &&
      (a.t - t0) / ms == (x.t - t0) / ms
  }

  function SelItems(core: BCore, s: LSel, adms: seq<Adm>, a: Act): seq<Act>
    decreases adms
  {
    if |adms| == 0 then
      [a]
    else
      (if AppliesL(s, adms[0].gid, adms[0].act.verb) && InScope(core.scope, a, adms[0].act) && InWindow(core.window, a, adms[0].act) then [adms[0].act] else []) + SelItems(core, s, adms[1..], a)
  }

  function ItemVals(core: BCore, items: seq<Act>, h: Hist): Option<seq<int>>
    decreases items
  {
    if |items| == 0 then
      Some([])
    else
      match EvalT(core.value, items[0], h) case Some(VQ(q)) => (if q.u != core.cap.u then None else match ItemVals(core, items[1..], h) case Some(r) => Some([q.n] + r) case None() => None) case _ /* _v12 */ => None
  }

  function SumI(xs: seq<int>): int
    decreases xs
  {
    if |xs| == 0 then
      0
    else
      xs[0] + SumI(xs[1..])
  }

  function MaxI(xs: seq<int>): int
    requires |xs| > 0
    decreases xs
  {
    if |xs| == 1 then
      xs[0]
    else
      var m: int := MaxI(xs[1..]); if xs[0] >= m then xs[0] else m
  }

  function KeyVals(core: BCore, items: seq<Act>): Option<seq<V>>
    decreases items
  {
    if |items| == 0 then
      Some([])
    else if core.key !in items[0].params then
      None
    else
      match KeyVals(core, items[1..]) case Some(r) => Some([items[0].params[core.key]] + r) case None() => None
  }

  function Dedup(vs: seq<V>): seq<V>
    decreases vs
  {
    if |vs| == 0 then
      []
    else if vs[0] in vs[1..] then
      Dedup(vs[1..])
    else
      [vs[0]] + Dedup(vs[1..])
  }

  function Exceeded(core: BCore, items: seq<Act>, h: Hist): Tri
    decreases core, items, h
  {
    match core.agg
    case ACount() =>
      B2T(|items| > core.cap.n)
    case ASum() =>
      (match ItemVals(core, items, h)
      case Some(xs) =>
        B2T(SumI(xs) > core.cap.n)
      case None() =>
        KU)
    case AMax() =>
      (match ItemVals(core, items, h)
      case Some(xs) =>
        if |xs| == 0 then
          KU
        else
          B2T(MaxI(xs) > core.cap.n)
      case None() =>
        KU)
    case ADistinct() =>
      match KeyVals(core, items)
      case Some(vs) =>
        B2T(|Dedup(vs)| > core.cap.n)
      case None() =>
        KU
  }

  function BoundStat(core: BCore, s: LSel, a: Act, h: Hist): Dec
    decreases core, s, a, h
  {
    var e: Tri := Exceeded(core, SelItems(core, s, h.adms, a), h);
    if e == KT then
      match core.onExceed
      case OnDeny() =>
        Deny
      case OnEscalate() =>
        Escalate
    else if e == KU then
      Escalate
    else
      Allow
  }

  function ValidityDec(v: Validity, dg: Delegation, a: Act, h: Hist): Dec
    decreases v, dg, a, h
  {
    if a.t < v.notBefore || a.t > v.notAfter then
      Deny
    else if v.maxIdle > 0 && h.last >= 0 && a.t - h.last > v.maxIdle then
      Deny
    else if a.depth < 0 || a.depth > dg.maxDepth then
      Deny
    else
      Allow
  }

  function DelegOk(dg: Delegation, gid: string, a: Act): bool
    decreases dg, gid, a
  {
    a.depth == 0 || gid in dg.mayTouch
  }

  function ProhOne(verbs: seq<string>, res: ResPat, c: Cond, a: Act, h: Hist): Dec
    decreases verbs, res, c, a, h
  {
    var m: Tri := AndK(B2T(a.verb in verbs), AndK(B2T(ResOk(res, a.res)), EvalC(c, a, h)));
    if m == KT then
      Deny
    else if m == KU then
      Escalate
    else
      Allow
  }

  function ProhDecG(ont: Ontology, ps: seq<Prohibit>, a: Act, h: Hist): Dec
    decreases ps
  {
    if |ps| == 0 then
      Allow
    else
      MeetD(ProhOne(ProhVerbs(ont, ps[0].target), ResolveSel(ont, ps[0].res), ps[0].cond, a, h), ProhDecG(ont, ps[1..], a, h))
  }

  function EscOne(m: Tri): Dec
    decreases m
  {
    if m == KF then
      Allow
    else
      Escalate
  }

  function EscDecG(cs: seq<Cond>, a: Act, h: Hist): Dec
    decreases cs
  {
    if |cs| == 0 then
      Allow
    else
      MeetD(EscOne(EvalC(cs[0], a, h)), EscDecG(cs[1..], a, h))
  }

  function BoundsDecG(ont: Ontology, bs: seq<Bound>, gid: string, a: Act, h: Hist): Dec
    decreases bs
  {
    if |bs| == 0 then
      Allow
    else
      var s: LSel := ResolveBSel(ont, bs[0].sel); MeetD(if AppliesL(s, gid, a.verb) then BoundStat(bs[0].core, s, a, h) else Allow, BoundsDecG(ont, bs[1..], gid, a, h))
  }

  function GrantMatch(ont: Ontology, g: Grant, dg: Delegation, a: Act, h: Hist): Tri
    decreases ont, g, dg, a, h
  {
    AndK(B2T(a.verb == g.verb && DelegOk(dg, g.gid, a)), AndK(B2T(ResOk(ResolveSel(ont, g.res), a.res)), EvalC(g.cond, a, h)))
  }

  function GrantDecG(ont: Ontology, g: Goal, gr: Grant, a: Act, h: Hist): Dec
    decreases ont, g, gr, a, h
  {
    MeetD(DecOfTri(GrantMatch(ont, gr, g.deleg, a, h)), BoundsDecG(ont, g.bounds, gr.gid, a, h))
  }

  function GrantsDecG(ont: Ontology, g: Goal, gs: seq<Grant>, a: Act, h: Hist): Dec
    decreases gs
  {
    if |gs| == 0 then
      Deny
    else
      JoinD(GrantDecG(ont, g, gs[0], a, h), GrantsDecG(ont, g, gs[1..], a, h))
  }

  function DG(ont: Ontology, g: Goal, a: Act, h: Hist): Dec
    decreases ont, g, a, h
  {
    MeetD(ValidityDec(g.validity, g.deleg, a, h), MeetD(ProhDecG(ont, g.prohibits, a, h), MeetD(EscDecG(g.escalateOn, a, h), GrantsDecG(ont, g, g.grants, a, h))))
  }

  function StrLt(a: string, b: string): bool
    decreases |a| + |b|
  {
    if |b| == 0 then
      false
    else if |a| == 0 then
      true
    else if a[0] != b[0] then
      a[0] as int < b[0] as int
    else
      StrLt(a[1..], b[1..])
  }

  predicate StrictlySorted(xs: seq<string>)
    decreases xs
  {
    |xs| <= 1 || (StrLt(xs[0], xs[1]) && StrictlySorted(xs[1..]))
  }

  predicate UnitOk(u: Unit)
    decreases u
  {
    match u
    case UMoney(c) =>
      |c| > 0
    case _ /* _v13 */ =>
      true
  }

  predicate TyOk(t: Ty)
    decreases t
  {
    match t
    case TyQ(u) =>
      UnitOk(u)
    case TyS() =>
      true
  }

  predicate VOk(v: V)
    decreases v
  {
    match v
    case VQ(q) =>
      UnitOk(q.u)
    case VS(_ /* _v14 */) =>
      true
    case VSet(items) =>
      forall i: int {:trigger items[i]} :: 
        0 <= i < |items| ==>
          match items[i] case AQ(q) => UnitOk(q.u) case AS(_ /* _v15 */) => true
  }

  function TypeOfTerm(t: Term): Option<Ty>
    decreases t
  {
    match t
    case Param(_ /* _v16 */, ty) =>
      Some(ty)
    case Lit(v) =>
      TypeOfV(v)
    case HistAgg(_ /* _v17 */, u) =>
      Some(TyQ(u))
  }

  predicate TermOk(t: Term)
    decreases t
  {
    match t
    case Param(p, ty) =>
      |p| > 0 &&
      TyOk(ty)
    case Lit(v) =>
      VOk(v)
    case HistAgg(b, u) =>
      |b| > 0 &&
      UnitOk(u)
  }

  predicate AllOfTy(items: seq<Atom>, ty: Ty)
    decreases items, ty
  {
    forall i: int {:trigger items[i]} :: 
      0 <= i < |items| ==>
        TypeOfV(AtomV(items[i])) == Some(ty)
  }

  predicate CmpTyped(op: Op, l: Term, r: Term)
    decreases op, l, r
  {
    TermOk(l) &&
    TermOk(r) &&
    TypeOfTerm(l).Some? &&
    match op case Eq() => TypeOfTerm(l) == TypeOfTerm(r) case Ne() => TypeOfTerm(l) == TypeOfTerm(r) case Lt() => TypeOfTerm(l) == TypeOfTerm(r) && TypeOfTerm(l).v.TyQ? case Lte() => TypeOfTerm(l) == TypeOfTerm(r) && TypeOfTerm(l).v.TyQ? case Gt() => TypeOfTerm(l) == TypeOfTerm(r) && TypeOfTerm(l).v.TyQ? case Gte() => TypeOfTerm(l) == TypeOfTerm(r) && TypeOfTerm(l).v.TyQ? case In() => r.Lit? && r.v.VSet? && AllOfTy(r.v.items, TypeOfTerm(l).v) case Nin() => r.Lit? && r.v.VSet? && AllOfTy(r.v.items, TypeOfTerm(l).v)
  }

  predicate CondTyped(c: Cond, ok: (string, Ty) -> bool)
    decreases c
  {
    match c
    case CTrue() =>
      true
    case Cmp(op, l, r) =>
      CmpTyped(op, l, r) &&
      ParamsOk(l, ok) &&
      ParamsOk(r, ok)
    case And(x, y) =>
      CondTyped(x, ok) &&
      CondTyped(y, ok)
    case Or(x, y) =>
      CondTyped(x, ok) &&
      CondTyped(y, ok)
    case Not(x) =>
      CondTyped(x, ok)
  }

  predicate ParamsOk(t: Term, ok: (string, Ty) -> bool)
    decreases t
  {
    match t
    case Param(p, ty) =>
      ok(p, ty)
    case _ /* _v18 */ =>
      true
  }

  function FindDecl(vs: seq<VerbDecl>, verb: string): Option<VerbDecl>
    decreases vs
  {
    if |vs| == 0 then
      None
    else if vs[0].verb == verb then
      Some(vs[0])
    else
      FindDecl(vs[1..], verb)
  }

  predicate HasParam(ps: seq<ParamDecl>, p: string, ty: Ty)
    decreases ps, p, ty
  {
    ParamDecl(p, ty) in ps
  }

  predicate DeclaredFor(ont: Ontology, verbs: seq<string>, p: string, ty: Ty)
    decreases ont, verbs, p, ty
  {
    forall i: int {:trigger verbs[i]} :: 
      (0 <= i < |verbs| ==>
        FindDecl(ont.verbs, verbs[i]).Some?) &&
      (0 <= i < |verbs| ==>
        HasParam(FindDecl(ont.verbs, verbs[i]).v.params, p, ty))
  }

  predicate NoConflictP(ps: seq<ParamDecl>, p: string, ty: Ty)
    decreases ps
  {
    |ps| == 0 || ((ps[0].path != p || ps[0].ty == ty) && NoConflictP(ps[1..], p, ty))
  }

  predicate NoConflict(vs: seq<VerbDecl>, p: string, ty: Ty)
    decreases vs
  {
    |vs| == 0 || (NoConflictP(vs[0].params, p, ty) && NoConflict(vs[1..], p, ty))
  }

  predicate ResSelOk(ont: Ontology, s: ResSel)
    decreases ont, s
  {
    match s
    case Exact(id) =>
      |id| > 0
    case OneOf(ids) =>
      |ids| > 0
    case Related(rel, anchor) =>
      exists i: int {:trigger ont.rels[i]} :: 
        0 <= i < |ont.rels| &&
        ont.rels[i].rel == rel &&
        ont.rels[i].anchor == anchor
    case AnyRes(_ /* _v19 */) =>
      true
    case AllOf(ps) =>
      |ps| >= 2 &&
      forall i: int {:trigger ps[i]} :: 
        0 <= i < |ps| ==>
          PartOk(ont, ps[i])
  }

  predicate PartOk(ont: Ontology, p: ResPart)
    decreases ont, p
  {
    match p
    case PartExact(id) =>
      |id| > 0
    case PartOneOf(ids) =>
      |ids| > 0
    case PartRelated(rel, anchor) =>
      exists i: int {:trigger ont.rels[i]} :: 
        0 <= i < |ont.rels| &&
        ont.rels[i].rel == rel &&
        ont.rels[i].anchor == anchor
  }

  predicate GrantOk(ont: Ontology, g: Goal, gr: Grant)
    decreases ont, g, gr
  {
    |gr.gid| > 0 &&
    FindDecl(ont.verbs, gr.verb).Some? &&
    ResSelOk(ont, gr.res) &&
    (gr.res.AnyRes? ==>
      gr.gid in g.wildcardAck) &&
    CondTyped(gr.cond, (p: string, ty: Ty) => DeclaredFor(ont, [gr.verb], p, ty))
  }

  predicate ProhibitOk(ont: Ontology, p: Prohibit)
    decreases ont, p
  {
    |p.pid| > 0 &&
    ResSelOk(ont, p.res) &&
    (match p.target case PVerb(v) => FindDecl(ont.verbs, v).Some? case PEffect(c) => |c| > 0 && |VerbsOfClass(ont.verbs, c)| > 0) &&
    CondTyped(p.cond, (q: string, ty: Ty) => DeclaredFor(ont, ProhVerbs(ont, p.target), q, ty))
  }

  predicate WindowOk(w: Window)
    decreases w
  {
    match w
    case WSliding(ms) =>
      ms > 0
    case WPeriod(ms, _ /* _v20 */) =>
      ms > 0
    case _ /* _v21 */ =>
      true
  }

  predicate ScopeOk(s: Scope)
    decreases s
  {
    match s
    case SFleet(ag) =>
      |ag| > 0
    case _ /* _v22 */ =>
      true
  }

  predicate BoundOk(ont: Ontology, g: Goal, b: Bound)
    decreases ont, g, b
  {
    |b.bid| > 0 &&
    TermOk(b.core.value) &&
    UnitOk(b.core.cap.u) &&
    b.core.cap.n >= 0 &&
    WindowOk(b.core.window) &&
    ScopeOk(b.core.scope) &&
    (match b.sel case SelGids(gids) => |gids| > 0 && (forall i: int {:trigger gids[i]} :: 0 <= i < |gids| ==> exists j: int {:trigger g.grants[j]} :: 0 <= j < |g.grants| && g.grants[j].gid == gids[i]) case SelEffect(c) => |c| > 0) &&
    match b.core.agg case ACount() => b.core.cap.u == UCount case ASum() => TypeOfTerm(b.core.value) == Some(TyQ(b.core.cap.u)) case AMax() => TypeOfTerm(b.core.value) == Some(TyQ(b.core.cap.u)) case ADistinct() => b.core.cap.u == UCount && |b.core.key| > 0
  }

  predicate ValidityOk(v: Validity, dg: Delegation, g: Goal)
    decreases v, dg, g
  {
    v.notBefore <= v.notAfter &&
    v.maxIdle >= 0 &&
    0 <= dg.maxDepth <= 16 &&
    dg.narrowOnly &&
    forall i: int {:trigger dg.mayTouch[i]} :: 
      0 <= i < |dg.mayTouch| ==>
        exists j: int {:trigger g.grants[j]} :: 
          0 <= j < |g.grants| &&
          g.grants[j].gid == dg.mayTouch[i]
  }

  predicate HoleOk(g: Goal, h: Hole)
    decreases g, h
  {
    |h.hid| > 0 &&
    forall i: int {:trigger h.affects[i]} :: 
      0 <= i < |h.affects| ==>
        exists j: int {:trigger g.grants[j]} :: 
          0 <= j < |g.grants| &&
          g.grants[j].gid == h.affects[i]
  }

  function Gids(gs: seq<Grant>): seq<string>
    decreases gs
  {
    seq(|gs|, (i: int) requires 0 <= i < |gs| => gs[i].gid)
  }

  function Pids(ps: seq<Prohibit>): seq<string>
    decreases ps
  {
    seq(|ps|, (i: int) requires 0 <= i < |ps| => ps[i].pid)
  }

  function Bids(bs: seq<Bound>): seq<string>
    decreases bs
  {
    seq(|bs|, (i: int) requires 0 <= i < |bs| => bs[i].bid)
  }

  function Hids(hs: seq<Hole>): seq<string>
    decreases hs
  {
    seq(|hs|, (i: int) requires 0 <= i < |hs| => hs[i].hid)
  }

  predicate EscsTyped(ont: Ontology, g: Goal)
    decreases ont, g
  {
    forall i: int {:trigger g.escalateOn[i]} :: 
      0 <= i < |g.escalateOn| ==>
        CondTyped(g.escalateOn[i], (p: string, ty: Ty) => NoConflict(ont.verbs, p, ty))
  }

  predicate Sorted4(g: Goal)
    decreases g
  {
    StrictlySorted(Gids(g.grants)) &&
    StrictlySorted(Pids(g.prohibits)) &&
    StrictlySorted(Bids(g.bounds)) &&
    StrictlySorted(Hids(g.holes))
  }

  predicate IsWellTyped(ont: Ontology, g: Goal)
    decreases ont, g
  {
    Sorted4(g) &&
    (forall i: int {:trigger g.grants[i]} :: 
      0 <= i < |g.grants| ==>
        GrantOk(ont, g, g.grants[i])) &&
    (forall i: int {:trigger g.prohibits[i]} :: 
      0 <= i < |g.prohibits| ==>
        ProhibitOk(ont, g.prohibits[i])) &&
    (forall i: int {:trigger g.bounds[i]} :: 
      0 <= i < |g.bounds| ==>
        BoundOk(ont, g, g.bounds[i])) &&
    EscsTyped(ont, g) &&
    ValidityOk(g.validity, g.deleg, g) &&
    forall i: int {:trigger g.holes[i]} :: 
      0 <= i < |g.holes| ==>
        HoleOk(g, g.holes[i])
  }

  predicate Signable(ont: Ontology, g: Goal)
    decreases ont, g
  {
    IsWellTyped(ont, g) &&
    |g.holes| == 0
  }

  ghost predicate ActConforms(ont: Ontology, a: Act)
    decreases ont, a
  {
    FindDecl(ont.verbs, a.verb).Some? ==>
      forall i: int {:trigger FindDecl(ont.verbs, a.verb).v.params[i]} :: 
        0 <= i < |FindDecl(ont.verbs, a.verb).v.params| ==>
          ghost var pd: ParamDecl := FindDecl(ont.verbs, a.verb).v.params[i]; pd.path in a.params ==> TypeOfV(a.params[pd.path]) == Some(pd.ty)
  }

  ghost predicate TermConforms(t: Term, a: Act, h: Hist)
    decreases t, a, h
  {
    match t
    case Param(p, ty) =>
      p in a.params ==>
        TypeOfV(a.params[p]) == Some(ty)
    case Lit(_ /* _v23 */) =>
      true
    case HistAgg(b, u) =>
      b in h.aggs ==>
        h.aggs[b].u == u
  }

  ghost predicate Mix(op: Op, x: Option<V>, y: Option<V>)
    decreases op, x, y
  {
    x.Some? &&
    y.Some? &&
    match op case In() => !(y.v.VSet? && forall i: int {:trigger y.v.items[i]} :: (0 <= i < |y.v.items| ==> TypeOfV(x.v).Some?) && (0 <= i < |y.v.items| ==> TypeOfV(AtomV(y.v.items[i])) == TypeOfV(x.v))) case Nin() => !(y.v.VSet? && forall i: int {:trigger y.v.items[i]} :: (0 <= i < |y.v.items| ==> TypeOfV(x.v).Some?) && (0 <= i < |y.v.items| ==> TypeOfV(AtomV(y.v.items[i])) == TypeOfV(x.v))) case _ /* _v24 */ => !(TypeOfV(x.v).Some? && TypeOfV(x.v) == TypeOfV(y.v))
  }

  ghost predicate NoMix(c: Cond, a: Act, h: Hist)
    decreases c
  {
    match c
    case CTrue() =>
      true
    case Cmp(op, l, r) =>
      !Mix(op, EvalT(l, a, h), EvalT(r, a, h))
    case And(x, y) =>
      NoMix(x, a, h) &&
      NoMix(y, a, h)
    case Or(x, y) =>
      NoMix(x, a, h) &&
      NoMix(y, a, h)
    case Not(x) =>
      NoMix(x, a, h)
  }

  ghost predicate CondConforms(c: Cond, a: Act, h: Hist)
    decreases c
  {
    match c
    case CTrue() =>
      true
    case Cmp(_ /* _v25 */, l, r) =>
      TermConforms(l, a, h) &&
      TermConforms(r, a, h)
    case And(x, y) =>
      CondConforms(x, a, h) &&
      CondConforms(y, a, h)
    case Or(x, y) =>
      CondConforms(x, a, h) &&
      CondConforms(y, a, h)
    case Not(x) =>
      CondConforms(x, a, h)
  }

  lemma TermTy(t: Term, a: Act, h: Hist)
    requires TermConforms(t, a, h)
    ensures EvalT(t, a, h).Some? ==> TypeOfV(EvalT(t, a, h).v) == TypeOfTerm(t)
    decreases t, a, h
  {
    match t
    case {:split false} Param(_ /* _v26 */, _ /* _v27 */) =>
    case {:split false} Lit(_ /* _v28 */) =>
    case {:split false} HistAgg(_ /* _v29 */, _ /* _v30 */) =>
  }

  lemma /*{:_inductionTrigger NoMix(c, a, h)}*/ /*{:_inductionTrigger CondConforms(c, a, h)}*/ /*{:_induction c, a, h}*/ UnitSafety(c: Cond, ok: (string, Ty) -> bool, a: Act, h: Hist)
    requires CondTyped(c, ok) && CondConforms(c, a, h)
    ensures NoMix(c, a, h)
    decreases c
  {
    match c
    case {:split false} CTrue() =>
    case {:split false} Cmp(op, l, r) =>
      assert CmpTyped(op, l, r);
      TermTy(l, a, h);
      TermTy(r, a, h);
      ghost var x := EvalT(l, a, h);
      ghost var y := EvalT(r, a, h);
      if x.Some? && y.Some? && (op == In || op == Nin) {
        assert r.Lit? && r.v.VSet?;
        assert y == Some(r.v);
        assert AllOfTy(r.v.items, TypeOfTerm(l).v);
      }
    case {:split false} And(x, y) =>
      UnitSafety(x, ok, a, h);
      UnitSafety(y, ok, a, h);
    case {:split false} Or(x, y) =>
      UnitSafety(x, ok, a, h);
      UnitSafety(y, ok, a, h);
    case {:split false} Not(x) =>
      UnitSafety(x, ok, a, h);
  }

  type Dec = d: int
    | 0 <= d <= 2

  type Tri = t: int
    | 0 <= t <= 2

  datatype Unit = UMoney(ccy: string) | UCount | UDuration | UInstant | UBytes | URatio

  datatype Q = Q(u: Unit, n: int)

  datatype Atom = AQ(q: Q) | AS(s: string)

  datatype V = VQ(q: Q) | VS(s: string) | VSet(items: seq<Atom>)

  datatype Ty = TyQ(u: Unit) | TyS

  datatype Option<T> = None | Some(v: T)

  datatype Term = Param(path: string, ty: Ty) | Lit(v: V) | HistAgg(bid: string, u: Unit)

  datatype Op = Eq | Ne | Lt | Lte | Gt | Gte | In | Nin

  datatype Cond = CTrue | Cmp(op: Op, l: Term, r: Term) | And(a: Cond, b: Cond) | Or(a: Cond, b: Cond) | Not(c: Cond)

  datatype ResPart = PartExact(id: string) | PartOneOf(ids: seq<string>) | PartRelated(rel: string, anchor: string)

  datatype ResSel = Exact(id: string) | OneOf(ids: seq<string>) | Related(rel: string, anchor: string) | AnyRes(reason: string) | AllOf(parts: seq<ResPart>)

  datatype Grant = Grant(gid: string, verb: string, res: ResSel, cond: Cond)

  datatype ProhTarget = PVerb(verb: string) | PEffect(cls: string)

  datatype Prohibit = Prohibit(pid: string, target: ProhTarget, res: ResSel, cond: Cond)

  datatype Agg = ACount | ASum | AMax | ADistinct

  datatype Sel = SelGids(gids: seq<string>) | SelEffect(cls: string)

  datatype Window = WTask | WSliding(ms: int) | WPeriod(ms: int, t0: int) | WLifetime

  datatype Scope = SSession | SPrincipal | SOrg | SFleet(agents: seq<string>)

  datatype OnExceed = OnDeny | OnEscalate

  datatype BCore = BCore(agg: Agg, value: Term, key: string, window: Window, scope: Scope, cap: Q, onExceed: OnExceed)

  datatype Bound = Bound(bid: string, sel: Sel, core: BCore)

  datatype Validity = Validity(notBefore: int, notAfter: int, maxIdle: int)

  datatype Delegation = Delegation(maxDepth: int, narrowOnly: bool, mayTouch: seq<string>)

  datatype Hole = Hole(hid: string, q: string, domain: seq<string>, affects: seq<string>, global: bool)

  datatype Goal = Goal(v: int, principal: string, ontDigest: string, nlDigest: string, sources: seq<string>, grants: seq<Grant>, prohibits: seq<Prohibit>, bounds: seq<Bound>, validity: Validity, deleg: Delegation, escalateOn: seq<Cond>, wildcardAck: seq<string>, holes: seq<Hole>)

  datatype ParamDecl = ParamDecl(path: string, ty: Ty)

  datatype VerbDecl = VerbDecl(verb: string, cls: string, params: seq<ParamDecl>)

  datatype RelDecl = RelDecl(rel: string, anchor: string, members: seq<string>)

  datatype Ontology = Ontology(verbs: seq<VerbDecl>, rels: seq<RelDecl>)

  datatype Act = Act(verb: string, res: string, params: map<string, V>, t: int, sess: string, prin: string, org: string, agent: string, depth: int)

  datatype Adm = Adm(gid: string, act: Act)

  datatype Hist = Hist(adms: seq<Adm>, last: int, aggs: map<string, Q>)

  datatype ResPat = PStar | PSet(ids: seq<string>)

  datatype LSel = LSel(gids: seq<string>, verbs: seq<string>)
}

module GoalWitness {
  function Applicable(cs: seq<LCeil>, gid: string, verb: string): seq<string>
    decreases cs
  {
    if |cs| == 0 then
      []
    else
      (if AppliesL(cs[0].sel, gid, verb) then [cs[0].bid] else []) + Applicable(cs[1..], gid, verb)
  }

  function FindAllow(ps: seq<LPred>, ceils: seq<LCeil>, dg: Delegation, a: Act, h: Hist): Option<LPred>
    decreases ps
  {
    if |ps| == 0 then
      None
    else if PredDec(ps[0], ceils, dg, a, h) == Allow then
      Some(ps[0])
    else
      FindAllow(ps[1..], ceils, dg, a, h)
  }

  lemma /*{:_inductionTrigger FindAllow(ps, ceils, dg, a, h)}*/ /*{:_inductionTrigger PredsDecP(ps, ceils, dg, a, h)}*/ /*{:_induction ps, ceils, dg, a, h}*/ AllowHasWitness(ps: seq<LPred>, ceils: seq<LCeil>, dg: Delegation, a: Act, h: Hist)
    requires PredsDecP(ps, ceils, dg, a, h) == Allow
    ensures FindAllow(ps, ceils, dg, a, h).Some?
    ensures FindAllow(ps, ceils, dg, a, h).v in ps
    ensures PredDec(FindAllow(ps, ceils, dg, a, h).v, ceils, dg, a, h) == Allow
    decreases ps
  {
    if PredDec(ps[0], ceils, dg, a, h) != Allow {
      AllowHasWitness(ps[1..], ceils, dg, a, h);
    }
  }

  function DecideW(p: Pol, a: Act, h: Hist): (Dec, Wit)
    decreases p, a, h
  {
    var d: Dec := DP(p, a, h);
    if d == Allow then
      match FindAllow(p.preds, p.ceils, p.deleg, a, h)
      case Some(pr) =>
        (Allow, Wit(pr.gid, Applicable(p.ceils, pr.gid, a.verb)))
      case None() =>
        (Deny, Wit("""", []))
    else
      (d, Wit("""", []))
  }

  lemma DecideWAgrees(p: Pol, a: Act, h: Hist)
    ensures DecideW(p, a, h).0 == DP(p, a, h)
    decreases p, a, h
  {
    if DP(p, a, h) == Allow {
      AllowHasWitness(p.preds, p.ceils, p.deleg, a, h);
    }
  }

  predicate AnyPredAllows(ps: seq<LPred>, gid: string, ceils: seq<LCeil>, dg: Delegation, a: Act, h: Hist)
    decreases ps
  {
    |ps| > 0 &&
    ((ps[0].gid == gid && PredDec(ps[0], ceils, dg, a, h) == Allow) || AnyPredAllows(ps[1..], gid, ceils, dg, a, h))
  }

  function VerifyWitness(p: Pol, a: Act, h: Hist, w: Wit): bool
    decreases p, a, h, w
  {
    ValidityDec(p.validity, p.deleg, a, h) == Allow &&
    ProhDecP(p.prohs, a, h) == Allow &&
    EscDecP(p.escs, a, h) == Allow &&
    AnyPredAllows(p.preds, w.gid, p.ceils, p.deleg, a, h) &&
    w.bids == Applicable(p.ceils, w.gid, a.verb)
  }

  lemma /*{:_inductionTrigger AnyPredAllows(ps, gid, ceils, dg, a, h)}*/ /*{:_induction ps, ceils, dg, gid, a, h}*/ PredAbove(ps: seq<LPred>, ceils: seq<LCeil>, dg: Delegation, gid: string, a: Act, h: Hist)
    requires AnyPredAllows(ps, gid, ceils, dg, a, h)
    ensures PredsDecP(ps, ceils, dg, a, h) == Allow
    decreases ps
  {
    if !(ps[0].gid == gid && PredDec(ps[0], ceils, dg, a, h) == Allow) {
      PredAbove(ps[1..], ceils, dg, gid, a, h);
    }
  }

  lemma VerifyWitnessSound(p: Pol, a: Act, h: Hist, w: Wit)
    requires VerifyWitness(p, a, h, w)
    ensures DP(p, a, h) == Allow
    decreases p, a, h, w
  {
    PredAbove(p.preds, p.ceils, p.deleg, w.gid, a, h);
  }

  lemma VerifyWitnessComplete(p: Pol, a: Act, h: Hist)
    requires DP(p, a, h) == Allow
    ensures VerifyWitness(p, a, h, DecideW(p, a, h).1)
    decreases p, a, h
  {
    AllowHasWitness(p.preds, p.ceils, p.deleg, a, h);
    ghost var pr := FindAllow(p.preds, p.ceils, p.deleg, a, h).v;
    InPredsAllows(p.preds, pr, p.ceils, p.deleg, a, h);
  }

  lemma /*{:_inductionTrigger AnyPredAllows(ps, pr.gid, ceils, dg, a, h)}*/ /*{:_inductionTrigger PredDec(pr, ceils, dg, a, h), pr in ps}*/ /*{:_induction ps, ceils, dg, a, h}*/ InPredsAllows(ps: seq<LPred>, pr: LPred, ceils: seq<LCeil>, dg: Delegation, a: Act, h: Hist)
    requires pr in ps && PredDec(pr, ceils, dg, a, h) == Allow
    ensures AnyPredAllows(ps, pr.gid, ceils, dg, a, h)
    decreases ps
  {
    if ps[0] != pr {
      InTail(ps, pr);
      InPredsAllows(ps[1..], pr, ceils, dg, a, h);
    }
  }

  lemma /*{:_inductionTrigger EscDecP(p.escs, a, h)}*/ /*{:_inductionTrigger ProhDecP(p.prohs, a, h)}*/ /*{:_inductionTrigger ValidityDec(p.validity, p.deleg, a, h)}*/ /*{:_inductionTrigger DecideW(p, a, h)}*/ /*{:_induction a, h}*/ ProvenanceT3(p: Pol, a: Act, h: Hist)
    requires DecideW(p, a, h).0 == Allow
    ensures exists pr: LPred {:trigger PredDec(pr, p.ceils, p.deleg, a, h)} {:trigger pr.gid} {:trigger pr in p.preds} :: pr in p.preds && pr.gid == DecideW(p, a, h).1.gid && PredDec(pr, p.ceils, p.deleg, a, h) == Allow
    ensures DecideW(p, a, h).1.bids == Applicable(p.ceils, DecideW(p, a, h).1.gid, a.verb)
    ensures ValidityDec(p.validity, p.deleg, a, h) == Allow && ProhDecP(p.prohs, a, h) == Allow && EscDecP(p.escs, a, h) == Allow
    decreases p, a, h
  {
    DecideWAgrees(p, a, h);
    AllowHasWitness(p.preds, p.ceils, p.deleg, a, h);
    ghost var pr := FindAllow(p.preds, p.ceils, p.deleg, a, h).v;
    assert pr in p.preds && pr.gid == DecideW(p, a, h).1.gid && PredDec(pr, p.ceils, p.deleg, a, h) == Allow;
  }

  lemma TailSub<T>(xs: seq<T>, x: T)
    requires |xs| > 0 && x in xs[1..]
    ensures x in xs
    decreases xs
  {
    ghost var i :| 0 <= i < |xs[1..]| && xs[1..][i] == x;
    assert xs[i + 1] == x;
  }

  lemma /*{:_inductionTrigger LowerGrants(ont, gs)}*/ /*{:_induction ont, gs}*/ LowerKeepsGids(ont: Ontology, gs: seq<Grant>, pr: LPred)
    requires pr in LowerGrants(ont, gs)
    ensures exists gr: Grant {:trigger gr.gid} {:trigger gr in gs} :: gr in gs && gr.gid == pr.gid
    decreases gs
  {
    if |gs| > 0 {
      if pr == LowerGrants(ont, gs)[0] {
        assert gs[0] in gs;
      } else {
        InTail(LowerGrants(ont, gs), pr);
        LowerKeepsGids(ont, gs[1..], pr);
        ghost var gr :| gr in gs[1..] && gr.gid == pr.gid;
        TailSub(gs, gr);
      }
    }
  }

  lemma /*{:_inductionTrigger StripGrants(hs, gs)}*/ /*{:_induction hs, gs}*/ StripMember(hs: seq<Hole>, gs: seq<Grant>, gr: Grant)
    requires gr in StripGrants(hs, gs)
    ensures gr in gs
    decreases gs
  {
    if |gs| > 0 {
      if DependsOn(hs, gs[0].gid) {
        StripMember(hs, gs[1..], gr);
        TailSub(gs, gr);
      } else if gr == gs[0] {
        assert gr in gs;
      } else {
        InTail(StripGrants(hs, gs), gr);
        StripMember(hs, gs[1..], gr);
        TailSub(gs, gr);
      }
    }
  }

  lemma ProvenanceNamesAGrant(ont: Ontology, g: Goal, a: Act, h: Hist)
    requires Compile(ont, g).Compiled?
    requires DecideW(Compile(ont, g).p, a, h).0 == Allow
    ensures exists gr: Grant {:trigger gr.gid} {:trigger gr in g.grants} :: gr in g.grants && gr.gid == DecideW(Compile(ont, g).p, a, h).1.gid
    decreases ont, g, a, h
  {
    ghost var p := Compile(ont, g).p;
    ProvenanceT3(p, a, h);
    ghost var pr :| pr in p.preds && pr.gid == DecideW(p, a, h).1.gid && PredDec(pr, p.ceils, p.deleg, a, h) == Allow;
    LowerKeepsGids(ont, StripGrants(g.holes, g.grants), pr);
    ghost var gr :| gr in StripGrants(g.holes, g.grants) && gr.gid == pr.gid;
    StripMember(g.holes, g.grants, gr);
  }

  function PepAllows(d: Dec, ans: Option<Answer>, pd: string, ad: string, hh: string): bool
    decreases d, ans, pd, ad, hh
  {
    d == Allow || (d == Escalate && ans.Some? && ans.v.sigOk && ans.v.policyDigest == pd && ans.v.actionDigest == ad && ans.v.histHead == hh)
  }

  lemma PepT4(d: Dec, ans: Option<Answer>, pd: string, ad: string, hh: string)
    ensures PepAllows(d, ans, pd, ad, hh) ==> d == Allow || (d == Escalate && ans.Some? && ans.v.sigOk && ans.v.policyDigest == pd && ans.v.actionDigest == ad && ans.v.histHead == hh)
    ensures d == Deny ==> !PepAllows(d, ans, pd, ad, hh)
    ensures d == Escalate && ans.None? ==> !PepAllows(d, ans, pd, ad, hh)
    decreases d, ans, pd, ad, hh
  {
  }

  lemma NoAnswerReplay(ans: Answer, pd: string, ad: string, hh: string)
    requires ans.policyDigest != pd || ans.actionDigest != ad || ans.histHead != hh || !ans.sigOk
    ensures !PepAllows(Escalate, Some(ans), pd, ad, hh)
    decreases ans, pd, ad, hh
  {
  }

  import opened GoalIr

  import opened GoalCompile

  datatype Wit = Wit(gid: string, bids: seq<string>)

  datatype Answer = Answer(sigOk: bool, policyDigest: string, actionDigest: string, histHead: string)
}

module GoalCompile {
  function EvalN(c: NC, a: Act, h: Hist): Tri
    decreases c
  {
    match c
    case NTrue() =>
      KT
    case NFalse() =>
      KF
    case NAtom(op, l, r) =>
      CmpT(op, EvalT(l, a, h), EvalT(r, a, h))
    case NAnd(x, y) =>
      AndK(EvalN(x, a, h), EvalN(y, a, h))
    case NOr(x, y) =>
      OrK(EvalN(x, a, h), EvalN(y, a, h))
  }

  function Nnf(c: Cond, pos: bool): NC
    decreases c
  {
    match c
    case CTrue() =>
      if pos then
        NTrue
      else
        NFalse
    case Cmp(op, l, r) =>
      NAtom(if pos then op else NegOp(op), l, r)
    case And(x, y) =>
      if pos then
        NAnd(Nnf(x, true), Nnf(y, true))
      else
        NOr(Nnf(x, false), Nnf(y, false))
    case Or(x, y) =>
      if pos then
        NOr(Nnf(x, true), Nnf(y, true))
      else
        NAnd(Nnf(x, false), Nnf(y, false))
    case Not(x) =>
      Nnf(x, !pos)
  }

  lemma /*{:_inductionTrigger EvalN(Nnf(c, pos), a, h)}*/ /*{:_induction c, pos, a, h}*/ NnfSound(c: Cond, pos: bool, a: Act, h: Hist)
    ensures EvalN(Nnf(c, pos), a, h) == if pos then EvalC(c, a, h) else NotK(EvalC(c, a, h))
    decreases c
  {
    match c
    case {:split false} CTrue() =>
    case {:split false} Cmp(op, l, r) =>
      NegOpSound(op, EvalT(l, a, h), EvalT(r, a, h));
    case {:split false} And(x, y) =>
      NnfSound(x, pos, a, h);
      NnfSound(y, pos, a, h);
    case {:split false} Or(x, y) =>
      NnfSound(x, pos, a, h);
      NnfSound(y, pos, a, h);
    case {:split false} Not(x) =>
      NnfSound(x, !pos, a, h);
  }

  function ProhOneP(p: LProh, a: Act, h: Hist): Dec
    decreases p, a, h
  {
    var m: Tri := AndK(B2T(a.verb in p.verbs), AndK(B2T(ResOk(p.res, a.res)), EvalN(p.cond, a, h)));
    if m == KT then
      Deny
    else if m == KU then
      Escalate
    else
      Allow
  }

  function ProhDecP(ps: seq<LProh>, a: Act, h: Hist): Dec
    decreases ps
  {
    if |ps| == 0 then
      Allow
    else
      MeetD(ProhOneP(ps[0], a, h), ProhDecP(ps[1..], a, h))
  }

  function EscDecP(cs: seq<NC>, a: Act, h: Hist): Dec
    decreases cs
  {
    if |cs| == 0 then
      Allow
    else
      MeetD(EscOne(EvalN(cs[0], a, h)), EscDecP(cs[1..], a, h))
  }

  function CeilOne(c: LCeil, gid: string, a: Act, h: Hist): Dec
    decreases c, gid, a, h
  {
    if AppliesL(c.sel, gid, a.verb) then
      BoundStat(c.core, c.sel, a, h)
    else
      Allow
  }

  function CeilsDecP(cs: seq<LCeil>, gid: string, a: Act, h: Hist): Dec
    decreases cs
  {
    if |cs| == 0 then
      Allow
    else
      MeetD(CeilOne(cs[0], gid, a, h), CeilsDecP(cs[1..], gid, a, h))
  }

  function PredMatch(p: LPred, dg: Delegation, a: Act, h: Hist): Tri
    decreases p, dg, a, h
  {
    AndK(B2T(a.verb == p.verb && DelegOk(dg, p.gid, a)), AndK(B2T(ResOk(p.res, a.res)), EvalN(p.cond, a, h)))
  }

  function PredDec(p: LPred, ceils: seq<LCeil>, dg: Delegation, a: Act, h: Hist): Dec
    decreases p, ceils, dg, a, h
  {
    MeetD(DecOfTri(PredMatch(p, dg, a, h)), CeilsDecP(ceils, p.gid, a, h))
  }

  function PredsDecP(ps: seq<LPred>, ceils: seq<LCeil>, dg: Delegation, a: Act, h: Hist): Dec
    decreases ps
  {
    if |ps| == 0 then
      Deny
    else
      JoinD(PredDec(ps[0], ceils, dg, a, h), PredsDecP(ps[1..], ceils, dg, a, h))
  }

  function DP(p: Pol, a: Act, h: Hist): Dec
    decreases p, a, h
  {
    MeetD(ValidityDec(p.validity, p.deleg, a, h), MeetD(ProhDecP(p.prohs, a, h), MeetD(EscDecP(p.escs, a, h), PredsDecP(p.preds, p.ceils, p.deleg, a, h))))
  }

  function LowerGrants(ont: Ontology, gs: seq<Grant>): seq<LPred>
    decreases gs
  {
    if |gs| == 0 then
      []
    else
      [LPred(gs[0].gid, gs[0].verb, ResolveSel(ont, gs[0].res), Nnf(gs[0].cond, true))] + LowerGrants(ont, gs[1..])
  }

  function LowerProhs(ont: Ontology, ps: seq<Prohibit>): seq<LProh>
    decreases ps
  {
    if |ps| == 0 then
      []
    else
      [LProh(ps[0].pid, ProhVerbs(ont, ps[0].target), ResolveSel(ont, ps[0].res), Nnf(ps[0].cond, true))] + LowerProhs(ont, ps[1..])
  }

  function LowerBounds(ont: Ontology, bs: seq<Bound>): seq<LCeil>
    decreases bs
  {
    if |bs| == 0 then
      []
    else
      [LCeil(bs[0].bid, ResolveBSel(ont, bs[0].sel), bs[0].core)] + LowerBounds(ont, bs[1..])
  }

  function LowerEscs(cs: seq<Cond>): seq<NC>
    decreases cs
  {
    if |cs| == 0 then
      []
    else
      [Nnf(cs[0], true)] + LowerEscs(cs[1..])
  }

  function Lower(ont: Ontology, g: Goal): Pol
    decreases ont, g
  {
    Pol(LowerGrants(ont, g.grants), LowerProhs(ont, g.prohibits), LowerBounds(ont, g.bounds), LowerEscs(g.escalateOn), g.validity, g.deleg)
  }

  lemma /*{:_inductionTrigger ProhDecP(LowerProhs(ont, ps), a, h)}*/ /*{:_inductionTrigger ProhDecG(ont, ps, a, h)}*/ /*{:_induction ont, ps, a, h}*/ ProhEq(ont: Ontology, ps: seq<Prohibit>, a: Act, h: Hist)
    ensures ProhDecG(ont, ps, a, h) == ProhDecP(LowerProhs(ont, ps), a, h)
    decreases ps
  {
    if |ps| > 0 {
      NnfSound(ps[0].cond, true, a, h);
      ProhEq(ont, ps[1..], a, h);
    }
  }

  lemma /*{:_inductionTrigger EscDecP(LowerEscs(cs), a, h)}*/ /*{:_inductionTrigger EscDecG(cs, a, h)}*/ /*{:_induction cs, a, h}*/ EscEq(cs: seq<Cond>, a: Act, h: Hist)
    ensures EscDecG(cs, a, h) == EscDecP(LowerEscs(cs), a, h)
    decreases cs
  {
    if |cs| > 0 {
      NnfSound(cs[0], true, a, h);
      EscEq(cs[1..], a, h);
    }
  }

  lemma /*{:_inductionTrigger CeilsDecP(LowerBounds(ont, bs), gid, a, h)}*/ /*{:_inductionTrigger BoundsDecG(ont, bs, gid, a, h)}*/ /*{:_induction ont, bs, gid, a, h}*/ BoundsEq(ont: Ontology, bs: seq<Bound>, gid: string, a: Act, h: Hist)
    ensures BoundsDecG(ont, bs, gid, a, h) == CeilsDecP(LowerBounds(ont, bs), gid, a, h)
    decreases bs
  {
    if |bs| > 0 {
      BoundsEq(ont, bs[1..], gid, a, h);
    }
  }

  lemma /*{:_inductionTrigger PredsDecP(LowerGrants(ont, gs), LowerBounds(ont, g.bounds), g.deleg, a, h)}*/ /*{:_inductionTrigger GrantsDecG(ont, g, gs, a, h)}*/ /*{:_induction ont, g, gs, a, h}*/ GrantsEq(ont: Ontology, g: Goal, gs: seq<Grant>, a: Act, h: Hist)
    ensures GrantsDecG(ont, g, gs, a, h) == PredsDecP(LowerGrants(ont, gs), LowerBounds(ont, g.bounds), g.deleg, a, h)
    decreases gs
  {
    if |gs| > 0 {
      NnfSound(gs[0].cond, true, a, h);
      BoundsEq(ont, g.bounds, gs[0].gid, a, h);
      GrantsEq(ont, g, gs[1..], a, h);
    }
  }

  lemma LowerEquiv(ont: Ontology, g: Goal, a: Act, h: Hist)
    ensures DP(Lower(ont, g), a, h) == DG(ont, g, a, h)
    decreases ont, g, a, h
  {
    ProhEq(ont, g.prohibits, a, h);
    EscEq(g.escalateOn, a, h);
    GrantsEq(ont, g, g.grants, a, h);
  }

  function DependsOn(hs: seq<Hole>, gid: string): bool
    decreases hs
  {
    |hs| > 0 &&
    (hs[0].global || gid in hs[0].affects || DependsOn(hs[1..], gid))
  }

  function StripGrants(hs: seq<Hole>, gs: seq<Grant>): seq<Grant>
    decreases gs
  {
    if |gs| == 0 then
      []
    else
      (if DependsOn(hs, gs[0].gid) then [] else [gs[0]]) + StripGrants(hs, gs[1..])
  }

  function Strip(g: Goal): Goal
    decreases g
  {
    g.(grants := StripGrants(g.holes, g.grants), holes := [])
  }

  lemma StripNoHoles(g: Goal)
    requires |g.holes| == 0
    ensures Strip(g) == g
    decreases g
  {
    StripGrantsId(g.holes, g.grants);
  }

  lemma /*{:_inductionTrigger StripGrants(hs, gs)}*/ /*{:_induction hs, gs}*/ StripGrantsId(hs: seq<Hole>, gs: seq<Grant>)
    requires |hs| == 0
    ensures StripGrants(hs, gs) == gs
    decreases gs
  {
    if |gs| > 0 {
      StripGrantsId(hs, gs[1..]);
    }
  }

  function BadGrants(ont: Ontology, g: Goal, gs: seq<Grant>): seq<string>
    decreases gs
  {
    if |gs| == 0 then
      []
    else
      (if GrantOk(ont, g, gs[0]) then [] else [gs[0].gid]) + BadGrants(ont, g, gs[1..])
  }

  function BadProhibits(ont: Ontology, ps: seq<Prohibit>): seq<string>
    decreases ps
  {
    if |ps| == 0 then
      []
    else
      (if ProhibitOk(ont, ps[0]) then [] else [ps[0].pid]) + BadProhibits(ont, ps[1..])
  }

  function BadBounds(ont: Ontology, g: Goal, bs: seq<Bound>): seq<string>
    decreases bs
  {
    if |bs| == 0 then
      []
    else
      (if BoundOk(ont, g, bs[0]) then [] else [bs[0].bid]) + BadBounds(ont, g, bs[1..])
  }

  function BadHoles(g: Goal, hs: seq<Hole>): seq<string>
    decreases hs
  {
    if |hs| == 0 then
      []
    else
      (if HoleOk(g, hs[0]) then [] else [hs[0].hid]) + BadHoles(g, hs[1..])
  }

  function TypeReasons(ont: Ontology, g: Goal): seq<string>
    decreases ont, g
  {
    (if Sorted4(g) then [] else [""not_canonical_order""]) + (if |BadGrants(ont, g, g.grants)| == 0 then [] else [""ill_typed_grant""]) + (if |BadProhibits(ont, g.prohibits)| == 0 then [] else [""ill_typed_prohibit""]) + (if |BadBounds(ont, g, g.bounds)| == 0 then [] else [""ill_typed_bound""]) + (if EscsTyped(ont, g) then [] else [""ill_typed_escalation""]) + (if ValidityOk(g.validity, g.deleg, g) then [] else [""bad_validity_or_delegation""]) + if |BadHoles(g, g.holes)| == 0 then [] else [""bad_hole""]
  }

  lemma /*{:_inductionTrigger BadGrants(ont, g, gs)}*/ /*{:_induction ont, g, gs}*/ BadGrantsEmpty(ont: Ontology, g: Goal, gs: seq<Grant>)
    ensures |BadGrants(ont, g, gs)| == 0 <==> forall i: int {:trigger gs[i]} :: 0 <= i < |gs| ==> GrantOk(ont, g, gs[i])
    decreases gs
  {
    if |gs| > 0 {
      BadGrantsEmpty(ont, g, gs[1..]);
      assert forall i: int {:trigger gs[i]} :: 1 <= i < |gs| ==> gs[i] == gs[1..][i - 1];
    }
  }

  lemma /*{:_inductionTrigger BadProhibits(ont, ps)}*/ /*{:_induction ont, ps}*/ BadProhibitsEmpty(ont: Ontology, ps: seq<Prohibit>)
    ensures |BadProhibits(ont, ps)| == 0 <==> forall i: int {:trigger ps[i]} :: 0 <= i < |ps| ==> ProhibitOk(ont, ps[i])
    decreases ps
  {
    if |ps| > 0 {
      BadProhibitsEmpty(ont, ps[1..]);
      assert forall i: int {:trigger ps[i]} :: 1 <= i < |ps| ==> ps[i] == ps[1..][i - 1];
    }
  }

  lemma /*{:_inductionTrigger BadBounds(ont, g, bs)}*/ /*{:_induction ont, g, bs}*/ BadBoundsEmpty(ont: Ontology, g: Goal, bs: seq<Bound>)
    ensures |BadBounds(ont, g, bs)| == 0 <==> forall i: int {:trigger bs[i]} :: 0 <= i < |bs| ==> BoundOk(ont, g, bs[i])
    decreases bs
  {
    if |bs| > 0 {
      BadBoundsEmpty(ont, g, bs[1..]);
      assert forall i: int {:trigger bs[i]} :: 1 <= i < |bs| ==> bs[i] == bs[1..][i - 1];
    }
  }

  lemma /*{:_inductionTrigger BadHoles(g, hs)}*/ /*{:_induction g, hs}*/ BadHolesEmpty(g: Goal, hs: seq<Hole>)
    ensures |BadHoles(g, hs)| == 0 <==> forall i: int {:trigger hs[i]} :: 0 <= i < |hs| ==> HoleOk(g, hs[i])
    decreases hs
  {
    if |hs| > 0 {
      BadHolesEmpty(g, hs[1..]);
      assert forall i: int {:trigger hs[i]} :: 1 <= i < |hs| ==> hs[i] == hs[1..][i - 1];
    }
  }

  lemma ReasonsIffTyped(ont: Ontology, g: Goal)
    ensures |TypeReasons(ont, g)| == 0 <==> IsWellTyped(ont, g)
    decreases ont, g
  {
    BadGrantsEmpty(ont, g, g.grants);
    BadProhibitsEmpty(ont, g.prohibits);
    BadBoundsEmpty(ont, g, g.bounds);
    BadHolesEmpty(g, g.holes);
  }

  function Compile(ont: Ontology, g: Goal): CResult
    decreases ont, g
  {
    var rs: seq<string> := TypeReasons(ont, g);
    if |rs| > 0 then
      CEscalate(rs)
    else
      Compiled(Lower(ont, Strip(g)))
  }

  lemma SoundnessT1(ont: Ontology, g: Goal, a: Act, h: Hist)
    requires Compile(ont, g).Compiled? && |g.holes| == 0
    ensures DP(Compile(ont, g).p, a, h) == DG(ont, g, a, h)
    ensures DP(Compile(ont, g).p, a, h) == Allow ==> DG(ont, g, a, h) == Allow
    decreases ont, g, a, h
  {
    StripNoHoles(g);
    LowerEquiv(ont, g, a, h);
  }

  lemma DraftSemantics(ont: Ontology, g: Goal, a: Act, h: Hist)
    requires Compile(ont, g).Compiled?
    ensures DP(Compile(ont, g).p, a, h) == DG(ont, Strip(g), a, h)
    decreases ont, g, a, h
  {
    LowerEquiv(ont, Strip(g), a, h);
  }

  predicate ResNarrows(p2: ResPat, p1: ResPat)
    decreases p2, p1
  {
    p1.PStar? || (p2.PSet? && p1.PSet? && forall i: int {:trigger p2.ids[i]} :: 0 <= i < |p2.ids| ==> p2.ids[i] in p1.ids)
  }

  predicate CondNarrows(c2: Cond, c1: Cond)
    decreases c2, c1
  {
    c2 == c1 || (c2.And? && (c2.a == c1 || c2.b == c1))
  }

  predicate GrantNarrows(ont: Ontology, g2: Grant, g1: Grant)
    decreases ont, g2, g1
  {
    g2.gid == g1.gid &&
    g2.verb == g1.verb &&
    ResNarrows(ResolveSel(ont, g2.res), ResolveSel(ont, g1.res)) &&
    CondNarrows(g2.cond, g1.cond)
  }

  predicate SubsetOf<T(==)>(xs: seq<T>, ys: seq<T>)
    decreases xs, ys
  {
    forall i: int {:trigger xs[i]} :: 
      0 <= i < |xs| ==>
        xs[i] in ys
  }

  predicate Refines(ont: Ontology, g2: Goal, g1: Goal)
    decreases ont, g2, g1
  {
    (forall i: int {:trigger g2.grants[i]} :: 
      0 <= i < |g2.grants| ==>
        exists j: int {:trigger g1.grants[j]} :: 
          0 <= j < |g1.grants| &&
          GrantNarrows(ont, g2.grants[i], g1.grants[j])) &&
    SubsetOf(g1.prohibits, g2.prohibits) &&
    SubsetOf(g1.bounds, g2.bounds) &&
    SubsetOf(g1.escalateOn, g2.escalateOn) &&
    g2.validity.notBefore >= g1.validity.notBefore &&
    g2.validity.notAfter <= g1.validity.notAfter &&
    (g1.validity.maxIdle <= 0 || 0 < g2.validity.maxIdle <= g1.validity.maxIdle) &&
    g2.deleg.maxDepth <= g1.deleg.maxDepth &&
    SubsetOf(g2.deleg.mayTouch, g1.deleg.mayTouch)
  }

  lemma InTail<T>(xs: seq<T>, x: T)
    requires x in xs && xs[0] != x
    ensures x in xs[1..]
    decreases xs
  {
    ghost var i :| 0 <= i < |xs| && xs[i] == x;
    assert i >= 1;
    assert xs[1..][i - 1] == x;
  }

  lemma SubsetTail<T>(xs: seq<T>, ys: seq<T>)
    requires SubsetOf(xs, ys) && |xs| > 0
    ensures SubsetOf(xs[1..], ys) && xs[0] in ys
    decreases xs, ys
  {
    assert xs[0] in ys;
    forall i: int | 0 <= i < |xs[1..]|
      ensures xs[1..][i] in ys
    {
      assert xs[1..][i] == xs[i + 1];
    }
  }

  lemma SubsetMem<T>(xs: seq<T>, ys: seq<T>, x: T)
    requires SubsetOf(xs, ys) && x in xs
    ensures x in ys
    decreases xs, ys
  {
    ghost var i :| 0 <= i < |xs| && xs[i] == x;
  }

  lemma SubsetRefl<T>(xs: seq<T>)
    ensures SubsetOf(xs, xs)
    decreases xs
  {
  }

  lemma /*{:_inductionTrigger ProhOne(ProhVerbs(ont, p.target), ResolveSel(ont, p.res), p.cond, a, h), p in ps}*/ /*{:_inductionTrigger ProhDecG(ont, ps, a, h)}*/ /*{:_induction ont, ps, a, h}*/ ProhBelow(ont: Ontology, ps: seq<Prohibit>, p: Prohibit, a: Act, h: Hist)
    requires p in ps
    ensures ProhDecG(ont, ps, a, h) <= ProhOne(ProhVerbs(ont, p.target), ResolveSel(ont, p.res), p.cond, a, h)
    decreases ps
  {
    if ps[0] != p {
      InTail(ps, p);
      ProhBelow(ont, ps[1..], p, a, h);
    }
