  lemma /*{:_inductionTrigger ProhDecG(ont, ps1, a, h), ProhDecG(ont, ps2, a, h)}*/ /*{:_inductionTrigger ProhDecG(ont, ps2, a, h), SubsetOf(ps1, ps2)}*/ /*{:_induction ont, ps1, ps2, a, h}*/ ProhSuper(ont: Ontology, ps1: seq<Prohibit>, ps2: seq<Prohibit>, a: Act, h: Hist)
    requires SubsetOf(ps1, ps2)
    ensures ProhDecG(ont, ps2, a, h) <= ProhDecG(ont, ps1, a, h)
    decreases ps1
