    if cs[0] != c {
      InTail(cs, c);
      EscBelow(cs[1..], c, a, h);
    }
  }

  lemma /*{:_inductionTrigger EscDecG(cs1, a, h), EscDecG(cs2, a, h)}*/ /*{:_inductionTrigger EscDecG(cs2, a, h), SubsetOf(cs1, cs2)}*/ /*{:_induction cs1, cs2, a, h}*/ EscSuper(cs1: seq<Cond>, cs2: seq<Cond>, a: Act, h: Hist)
    requires SubsetOf(cs1, cs2)
    ensures EscDecG(cs2, a, h) <= EscDecG(cs1, a, h)
    decreases cs1
  {
    if |cs1| > 0 {
      EscBelow(cs2, cs1[0], a, h);
      SubsetTail(cs1, cs2);
      EscSuper(cs1[1..], cs2, a, h);
    }
