  function BoundOne(ont: Ontology, b: Bound, gid: string, a: Act, h: Hist): Dec
    decreases ont, b, gid, a, h
  {
    var s: LSel := ResolveBSel(ont, b.sel);
    if AppliesL(s, gid, a.verb) then
      BoundStat(b.core, s, a, h)
    else
      Allow
